@export var node_count: int = 12
@export var avg_degree: float = 2.2
@export var seed: int = 20250922

func _build_graph() -> void:
	var rng := RandomNumberGenerator.new()
	rng.seed = seed

	var V: Array = range(node_count)                    # vertices
	var E: Array = []                                     # edges

	var target_edges: int = int(node_count * avg_degree * 0.5)
	while E.size() < target_edges:
		var a: int = rng.randi_range(0, node_count - 1)
		var b: int = rng.randi_range(0, node_count - 1)
		if a != b and not _has_edge(E, a, b):
			E.append([a, b])

	# That's the graph. Two arrays.

@export var repulsion: float = 180.0
@export var edge_stiffness: float = 0.08
@export var damping: float = 0.82
@export var layout_iters: int = 250

func _relax(positions: Array, velocities: Array) -> void:
	for iter in layout_iters:
		for i in node_count:
			var force := Vector3.ZERO
			# Repulsion from every other node
			for j in node_count:
				if i == j: continue
				var delta: Vector3 = positions[i] - positions[j]
				var d: float = max(delta.length(), 0.1)
				force += delta.normalized() * (repulsion / (d * d))
			# Spring attraction along edges
			for edge in E:
				if edge[0] == i or edge[1] == i:
					var other: int = edge[1] if edge[0] == i else edge[0]
					var stretch: Vector3 = positions[other] - positions[i]
					force += stretch * edge_stiffness
			velocities[i] = (velocities[i] + force) * damping
			positions[i] += velocities[i] * 0.016

@export var room_scene: PackedScene
@export var portal_scene: PackedScene
@export var planar_layout: bool = true
@export var plane_y: float = 0.0
@export var plane_snap: float = 0.25

func _embed(positions: Array) -> void:
	for i in node_count:
		var pos: Vector3 = positions[i]
		if planar_layout:
			pos.y = lerp(pos.y, plane_y, plane_snap)
		var room = room_scene.instantiate()
		room.position = pos
		add_child(room)

	for edge in E:
		var a: Vector3 = positions[edge[0]]
		var b: Vector3 = positions[edge[1]]
		var bridge = portal_scene.instantiate()
		bridge.position = (a + b) * 0.5
		bridge.look_at(b, Vector3.UP)
		add_child(bridge)

enum StructureType { RANDOM, BY_DEGREE, BY_DISTANCE, SINGLE_TYPE, CUSTOM_PATTERN }

@export var structure_scenes: Array[PackedScene] = []
@export var structure_type: StructureType = StructureType.BY_DEGREE

func _assign_structure(node_index: int) -> PackedScene:
	match structure_type:
		StructureType.BY_DEGREE:
			var deg: int = _degree_of(node_index)
			var idx: int = clampi(deg, 0, structure_scenes.size() - 1)
			return structure_scenes[idx]
		StructureType.BY_DISTANCE:
			var d: int = _dijkstra_from_focal(node_index)
			return structure_scenes[clampi(d, 0, structure_scenes.size() - 1)]
		_:
			return structure_scenes[0]

@export var focal_node: int = 0

func _update_ambient() -> void:
	var distances: Array = _dijkstra(focal_node)
	var max_d: int = distances.max()
	for i in node_count:
		var room = get_child(i)
		var t: float = float(distances[i]) / max(float(max_d), 1.0)
		var light: Color = Color(1.0, 0.9, 0.7).lerp(Color(0.2, 0.3, 0.5), t)
		room.set_ambient(light)

